$failures=0;$check=static function(bool $ok,string $message)use(&$failures):void{echo($ok?'ok':'not ok').' - '.$message.PHP_EOL;if(!$ok)$failures++;};$throws=static function(callable $fn):bool{try{$fn();return false;}catch(DomainException|RuntimeException){return true;}};
$directory=sys_get_temp_dir().'/dxf-test-'.bin2hex(random_bytes(6));mkdir($directory,0700,true);
$make=static function(string $path,string $document,array $extra=[]):void{$zip=new ZipArchive();if($zip->open($path,ZipArchive::CREATE|ZipArchive::EXCL)!==true)throw new RuntimeException('fixture');$zip->addFromString('[Content_Types].xml','<?xml version="1.0"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>');$zip->addFromString('_rels/.rels','<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="r1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>');$zip->addFromString('word/document.xml',$document);foreach($extra as $name=>$value)$zip->addFromString($name,$value);$zip->close();};
$word='<?xml version="1.0"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body><w:p><w:r><w:t>{{person.</w:t></w:r><w:r><w:t>full_name}}</w:t></w:r></w:p></w:body></w:document>';
$source=$directory.'/source.docx';$make($source,$word);$descriptor=dxf_descriptor_validate(['schema'=>'docx-form/v1','document_filename'=>'result.docx','fields'=>[['key'=>'person.full_name','label'=>'Full name','type'=>'text','required'=>true,'max_length'=>160,'token'=>'{{person.full_name}}']], 'print'=>[]]);
