$output=$directory.'/output.docx';dxf_generate_docx($source,$descriptor,['person.full_name'=>'A < B & "quoted"'],$output);$zip=new ZipArchive();$zip->open($output);$xml=(string)$zip->getFromName('word/document.xml');$zip->close();$dom=dxf_xml_document($xml,'word/document.xml');$check(str_contains($dom->textContent,'A < B & "quoted"')&&!str_contains($xml,'< B'),'user values are serialized as XML text, not markup');
