$external=$directory.'/external.docx';$make($external,$word,['word/_rels/document.xml.rels'=>'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="x" TargetMode="External" Target="https://example.test/x"/></Relationships>']);$check($throws(static fn()=>dxf_validate_docx($external,$descriptor)),'external relationships are rejected');
$attachedRelationship=$directory.'/attached-relationship.docx';$make($attachedRelationship,$word,['word/_rels/settings.xml.rels'=>'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="x" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/attachedTemplate" Target="template.dotx"/></Relationships>']);$check($throws(static fn()=>dxf_validate_docx($attachedRelationship,$descriptor)),'attached-template relationship types are rejected');
$macro=$directory.'/macro.docx';$make($macro,$word,['word/vbaProject.bin'=>'binary']);$check($throws(static fn()=>dxf_validate_docx($macro,$descriptor)),'macro payloads are rejected');
$encrypted=$directory.'/encrypted.docx';$make($encrypted,$word);$encryptedZip=new ZipArchive();$encryptedZip->open($encrypted);$encryptedZip->setPassword('fixture-password');$encryptedSet=$encryptedZip->setEncryptionName('word/document.xml',ZipArchive::EM_AES_256,'fixture-password');$encryptedZip->close();$check($encryptedSet&&$throws(static fn()=>dxf_validate_docx($encrypted,$descriptor)),'encrypted entries are rejected');
$bomb=$directory.'/ratio.docx';$make($bomb,$word,['word/media/blob.bin'=>str_repeat("\0",1048576)]);$check($throws(static fn()=>dxf_validate_docx($bomb,$descriptor)),'unsafe compression ratios are rejected');
$malformed=$directory.'/malformed.docx';$make($malformed,'<w:document>');$check($throws(static fn()=>dxf_validate_docx($malformed,$descriptor)),'malformed XML is rejected');
$doctype=$directory.'/doctype.docx';$make($doctype,'<?xml version="1.0"?><!DOCTYPE x [<!ENTITY e "x">]><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body><w:p><w:r><w:t>&e;{{person.full_name}}</w:t></w:r></w:p></w:body></w:document>');$check($throws(static fn()=>dxf_validate_docx($doctype,$descriptor)),'DOCTYPE and entity declarations are rejected');
$utf16=$directory.'/utf16.docx';$make($utf16,"\xFF\xFE".mb_convert_encoding('<?xml version="1.0" encoding="UTF-16"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"/>','UTF-16LE','UTF-8'));$check($throws(static fn()=>dxf_validate_docx($utf16,$descriptor)),'non-UTF-8 XML is rejected');
$active=['fldSimple'=>'<w:fldSimple w:instr="INCLUDETEXT https://example.test/x"/>','fldChar'=>'<w:fldChar w:fldCharType="begin"/>','instrText'=>'<w:instrText>DDEAUTO calc</w:instrText>','dataBinding'=>'<w:dataBinding w:xpath="/x"/>','attachedTemplate'=>'<w:attachedTemplate/>','customXml'=>'<w:customXml><w:r><w:t>x</w:t></w:r></w:customXml>'];
foreach($active as $name=>$markup){$path=$directory.'/active-'.$name.'.docx';$make($path,'<?xml version="1.0"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>'.$markup.'<w:p><w:r><w:t>{{person.full_name}}</w:t></w:r></w:p></w:body></w:document>');$check($throws(static fn()=>dxf_validate_docx($path,$descriptor)),'Word '.$name.' constructs are rejected');}
foreach(scandir($directory)?:[] as $entry)if($entry!=='.'&&$entry!=='..')unlink($directory.'/'.$entry);rmdir($directory);exit($failures===0?0:1);
